// 卡帧关系：control 在卡帧 0 开段计时；OPENING_BUFFER=120 后 spawn 源 Boss，
// 从卡帧 120 起执行 BossCard3 入口。源 setInterrupt 超时窗口 3600 帧，
// TIME_LIMIT = 120 + 3600 + 4 = 3724。
// 入口 st06bs.ecl.txt:1211/1225 的 etCancel(640)、1231 funcSet(0)、1232 laserCancel、
// 1222-1223 killAllAsync/enmKillAll 在独立无敌卡的新敌上均无对象，保留为注释/一次清弹调用。
// 1248-1249 的 movePosTime 保留；moveLimit(0,144,240,64) 对静止停在 (0,144) 的 boss 不生效，
// 且目标没有恒久限位写口，省略。
const TH15_FIREBALL_RED: int = 752;
const TH15_FIREBALL_PURPLE: int = 768;
const TH15_FIREBALL_BLUE: int = 784;
