const SPELL_ID: int = 86;
const SOURCE_BONUS: int = 500000;

// 源每颗弹的 EX 记录（609/611）：
//   0x2  ANIM a=1        -> 出生退位移 4*speed = 0.8px，按已核口径在 fire 坐标里保留
//   0x100000 BRIGHT 0    -> 纯混合表现，省略
//   0x80000000 WAIT 200  -> @200
//   0x200000 VELTIME a=120, r=1.4/1.8, s=-999999(保留角) 或 -1.5707964
// 目标用 120 帧线性 step_speed 表达同一标量升速；方向与源 VELTIME 一致。
xformdef KEEP_RAMP(dest: fx) {
    @200 add_speed(0fx);
    step_speed(dest, 120 + 65536 * EASE_LINEAR);
}
// at() 的 VELTIME s=-1.5707964：200 帧后转向正上再升速。
xformdef TURN_UP_RAMP(dest: fx) {
    @200 add_speed(0fx);
    set_angle(-90deg);
    step_speed(dest, 120 + 65536 * EASE_LINEAR);
}

// ---- BossCard3_at (source 1291-1328): sprite 25, aim3 ring 1x1 ----
// 每外圈内 5 发；x 带 [D-C,D+C] 右移收窄，y 由 448 上移 208，弹角 90deg±10deg。
sub at_body(f0: fx, dest: fx) {
    var b: fx = 448fx;
    var c: fx = 160fx;
    var d: fx = -32fx * f0;
    for j in 0..16 {
        for k in 0..5 {
            var ux: fx = ((rand(65536) - 32768) as fx) / 32768;
            var x: fx = c * ux + d;
            var ua: fx = ((rand(65536) - 32768) as fx) / 32768;
            var a: angle = 90deg + (((1820fx * ua) as int) as angle);
            var uy: fx = ((rand(65536) - 32768) as fx) / 32768;
            var y: fx = b + 8fx * uy;
            x = x - 0.8fx * cos(a);
            y = y - 0.8fx * sin(a);
            _ = fire(TH15_FIREBALL_RED, 0, x, y, 0.2fx, a, TURN_UP_RAMP(dest), none);
            wait(1);
        }
        c = c - 10fx;
        d = d + 12fx * f0;
        b = b - 16fx;
    }
}
async sub at_async(f0: fx, dest: fx) { at_body(f0, dest); }

