// ---- BossCard3_at5 (source 1443-1483): H/L only ----
// 每外圈内 8 发；半径 I 每外圈 +15。弹角 90deg+2pi*rand（整周），
// 出生点 = 角落 + I*(cos,sin)(F + pi/2*rand)。
// diffI(J,16,16,16,18)：Lunatic 外圈 18，其余用到本 sub 的 Hard 为 16。
sub at5_body(shape: int, ex: fx, ey: fx, base: angle, dest: fx, rings: int) {
    var r: fx = 0fx;
    for j in 0..rings {
        for k in 0..8 {
            var a: angle = 90deg + ((rand(65536) - 32768) as angle);
            var uo: fx = ((rand(65536) - 32768) as fx) / 32768;
            var oa: angle = base + (((16384fx * uo) as int) as angle);
            var x: fx = ex + r * cos(oa);
            var y: fx = ey + r * sin(oa);
            x = x - 0.8fx * cos(a);
            y = y - 0.8fx * sin(a);
            _ = fire(shape, 0, x, y, 0.2fx, a, KEEP_RAMP(dest), none);
            wait(1);
        }
        r = r + 15fx;
    }
}
async sub at5_async(shape: int, ex: fx, ey: fx, base: angle, dest: fx, rings: int) {
    at5_body(shape, ex, ey, base, dest, rings);
}

// ---- 源 BossCard3 主循环 (source 1176-1287) ----
async sub boss_card() {
    set_invuln(65535);
    set_hurtbox(28fx);   // source setHurtbox(56,56)：普通圆取 56*0.5
    set_hitbox(25fx);    // source setHitbox(50,50)：普通圆取 50*0.5；保留体碰
    // 入口清弹：独立卡入口没有残留敌弹；保留一次源 etCancel(640) 的等价清弹。
    clear_bullets_at(0fx, 128fx, 640fx, 0);
    // 1248: movePosTime(60, mode4=二次减速, 0, 144)
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);

    var f0: fx = 1fx;                  // %F0，每轮翻转
    var rank: int = global(GVAR_RANK);
    loop {
        wait(120);                     // 1176: wait(60)+wait(30)+wait(30)，anm/playSound 省略
        if rank >= 2 {
            // 1265: unless($DIFF>=2) -> H/L 四角 at5；L 速度 1.8，H 1.4。
            var dest: fx = 1.4fx;
            var rings: int = 16;
            if rank >= 3 {
                dest = 1.8fx;
                rings = 18;
            }
            spawn at5_async(TH15_FIREBALL_RED, -192fx, 0fx, 0deg, dest, rings);
            spawn at5_async(TH15_FIREBALL_PURPLE, 192fx, 0fx, 90deg, dest, rings);
            spawn at5_async(TH15_FIREBALL_BLUE, -192fx, 448fx, -90deg, dest, rings);
            at5_body(TH15_FIREBALL_YELLOW, 192fx, 448fx, 180deg, dest, rings);
        } else {
            if rank >= 1 {
                // 1272-1274: Normal 追加 at()/at2() async。
                spawn at_async(f0, 1.4fx);
                spawn at2_async(f0, 1.4fx);
            }
            // 1276-1277: at4() async + at3() 同步（同步调用阻塞 128 帧）。
            spawn at4_async(f0, 1.4fx);
            at3_body(f0, 1.4fx);
        }
        wait(400);                     // 1279
        f0 = -f0;                      // 1280
    }
}

// ---- 训练外壳：control 承载段计时，120 帧后 spawn 真实 Boss ----
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 4000, 0, 0, 0, boss_card);
    loop { wait(60); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    // 源 1240 setInterrupt(0,0,3600) + 1242 spell(86,3600,500000,name)；
    // 本卡把 120 帧开场缓冲一起计入 TIME_LIMIT，源窗口仍为 3600。
    spell_begin(0, SPELL_ID, pattern, TIME_LIMIT, SOURCE_BONUS, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
